// Package norm implements the Unicode normalisation forms NFD and NFC (UAX #15,
// https://www.unicode.org/reports/tr15/) with the standard library only. The tables (tables.go) are generated by
// tools/genucd from the Unicode Character Database of the version in UnicodeVersion; Hangul syllables are
// decomposed and composed algorithmically (Unicode core specification, section 3.12).
package norm

import (
	"sort"
	"unicode/utf8"
)

type cccRange struct {
	lo, hi rune
	ccc    uint8
}

type decomposition struct {
	r    rune
	full string
}

type composition struct {
	first, second, composite rune
}

// Hangul syllable constants (Unicode core specification, section 3.12).
const (
	sBase  = 0xAC00
	lBase  = 0x1100
	vBase  = 0x1161
	tBase  = 0x11A7
	lCount = 19
	vCount = 21
	tCount = 28
	nCount = vCount * tCount
	sCount = lCount * nCount
)

// CCC returns the canonical combining class of r.
func CCC(r rune) uint8 {
	i := sort.Search(len(cccRanges), func(i int) bool { return cccRanges[i].hi >= r })
	if i < len(cccRanges) && cccRanges[i].lo <= r {
		return cccRanges[i].ccc
	}
	return 0
}

// decompose appends the full canonical decomposition of r to out.
func decompose(out []rune, r rune) []rune {
	if s := r - sBase; s >= 0 && s < sCount {
		out = append(out, lBase+s/nCount, vBase+(s%nCount)/tCount)
		if t := s % tCount; t != 0 {
			out = append(out, tBase+t)
		}
		return out
	}
	i := sort.Search(len(decompositions), func(i int) bool { return decompositions[i].r >= r })
	if i < len(decompositions) && decompositions[i].r == r {
		for _, c := range decompositions[i].full {
			out = append(out, c)
		}
		return out
	}
	return append(out, r)
}

// compose returns the primary composite of a and b, if there is one.
func compose(a, b rune) (rune, bool) {
	if l, v := a-lBase, b-vBase; l >= 0 && l < lCount && v >= 0 && v < vCount {
		return sBase + (l*vCount+v)*tCount, true
	}
	if s, t := a-sBase, b-tBase; s >= 0 && s < sCount && s%tCount == 0 && t > 0 && t < tCount {
		return a + t, true
	}
	i := sort.Search(len(compositions), func(i int) bool {
		c := compositions[i]
		return c.first > a || c.first == a && c.second >= b
	})
	if i < len(compositions) && compositions[i].first == a && compositions[i].second == b {
		return compositions[i].composite, true
	}
	return 0, false
}

// nfd returns the canonical decomposition of s in canonical order.
func nfd(s string) []rune {
	out := make([]rune, 0, len(s))
	for _, r := range s {
		out = decompose(out, r)
	}
	// canonical ordering: a stable sort of every run of non-starters by combining class
	for i := 0; i < len(out); {
		if CCC(out[i]) == 0 {
			i++
			continue
		}
		j := i
		for j < len(out) && CCC(out[j]) != 0 {
			j++
		}
		run := out[i:j]
		sort.SliceStable(run, func(a, b int) bool { return CCC(run[a]) < CCC(run[b]) })
		i = j
	}
	return out
}

// NFD returns s in Normalization Form D.
func NFD(s string) string {
	if ascii(s) {
		return s
	}
	return string(nfd(s))
}

// NFC returns s in Normalization Form C.
func NFC(s string) string {
	if ascii(s) {
		return s
	}
	d := nfd(s)
	out := d[:0] // composition only shrinks, so it can work in place
	starter := -1
	last := -1 // combining class of the last code point kept after the starter; -1: none
	for _, c := range d {
		cc := int(CCC(c))
		if starter >= 0 && (last == -1 || last < cc) {
			if p, ok := compose(out[starter], c); ok {
				out[starter] = p
				continue
			}
		}
		if cc == 0 {
			starter, last = len(out), -1
		} else {
			last = cc
		}
		out = append(out, c)
	}
	return string(out)
}

// IsNFC reports whether s is in Normalization Form C.
func IsNFC(s string) bool { return NFC(s) == s }

func ascii(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] >= utf8.RuneSelf {
			return false
		}
	}
	return true
}
